def front():
    p('Исследовательский отчёт','Section line');p('Эксперименты с памятью языковых агентов','Title')
    p('Проверка границ поиска, перенос одного примера между версиями API и стоимость повторного чтения','Lead')
    p('Наиболее устойчивый положительный результат получен в контролируемом симуляторе. Если запросы затрагивают связанные поля одного дорогого источника, совместный выбор записей иногда экономит чтения. Для двух способов подачи памяти языковой модели сильные простые контроли оказались конкурентоспособными.')
    tbl(['Исследовательский вопрос','Наблюдаемый результат','Что следует из пилота'],[
        ['Помогает ли карточка области поиска?','Sol: 8/12 с карточкой и 8/12 с сырым журналом. Luna: 4/12 и 3/12.','Сохранять границы имеет смысл для дальнейшей проверки. Дополнительная структуризация не дала устойчивого выигрыша.'],
        ['Помогает ли прошлый граничный пример?','Синтетические API: 8/12 с примером, 9/12 с новой пробой. Реальные пакеты: 6/6 в обоих условиях.','Агент способен придумать равноинформативную проверку. Подсказка о прошлом примере не гарантирует, что он будет применён.'],
        ['Какие факты выгодно сохранить вместе?','Совместный выбор: 0,998 чтения для полного ответа. Частотный кэш: 1,016. При поштучном чтении результаты совпали.','Изучать совместный выбор стоит там, где инструмент возвращает несколько связанных полей. Выигрыш пока установлен в симуляторе.']
    ],[4.4,6.25,6.45],True)
    h('Объём и проверка')
    p('120 исследовательских вызовов Codex CLI с зарегистрированными ответами, 12 поисковых задач, 6 искусственных семейств API, 12 подлинных дистрибутивов трёх Python-пакетов и 64 моделируемых мира. Дополнительно проверены 48 независимых от прежнего обзора опубликованных историй из 12 проектов. Один и тот же сценарий в разных условиях не увеличивает размер независимой выборки.')
    p('Все результаты, в том числе неудачные решения, полный ход инструментальных вызовов, исходные параметры и код входят в этот документ в виде таблиц и машиночитаемого приложения. Дополнительный ZIP содержит идентичную копию приложения.','Caption')
def real_page():
    page('Опыт 2   /   внешняя репликация','Проверка на реальных версиях Python-пакетов','На искусственных функциях агент с карточкой иногда выбирал неинформативную пробу. Чтобы проверить перенос этого наблюдения, взяты три известных изменения настоящих библиотек. Версию библиотеки исполнитель не видел.')
    tbl(['Пакет','Релизы для записи опыта','Целевые релизы','Что различала проба'],[
        ['packaging','20.9 и 22.0','21.3 и 23.0','Строка вне формата PEP 440 возвращает LegacyVersion или вызывает InvalidVersion.'],
        ['PyJWT','1.7.0 и 2.0.0','1.7.1 и 2.0.1','Декодирование с корректной подписью без списка algorithms успешно либо вызывает DecodeError.'],
        ['more-itertools','8.4.0 и 8.6.0','8.5.0 и 8.7.0','Неполный последний блок при strict=True даёт TypeError либо ValueError.']
    ],[3.1,3.45,3.3,7.25],True)
    p('Каждый исторический и целевой релиз получен как исходный wheel с PyPI. Его SHA-256 сверен с опубликованными метаданными. Изолированный интерпретатор исполнял подлинный код пакета. Старые и целевые файлы релизов различны, но некоторые целевые версии хронологически предшествуют более новому историческому примеру. Проверялся перенос между скрытыми развертываниями. Это не полное моделирование обновления по времени.')
    r=J('probe_real/summary.json')['arms'];rows=[]
    for a,l in [('archive','С примером'),('fresh','Свежая проба')]:
        x=r[a];rows.append([l,f"{x['perfect']}/6",f"{x['correct_outputs']}/24",f"{x['informative_probes']}/6",f"{x['exact_replays']}/6"])
    tbl(['Условие','Задач целиком','Верных значений','Информативная проба','Повторён исходный вход'],rows,[3.35,2.75,3.05,3.85,4.1],True)
    p('Условия получили одинаковое описание интерфейса и бюджет в одну пробу. Со старым примером модель дословно воспроизвела прошлый вход 5 раз из 6. При самостоятельном выборе она каждый раз нашла другую проверку, способную различить версии. Ни один пробный вход точно не совпал с оцениваемым. Например, самостоятельно предложенные строки «1.0-final» и «1.0_1» разделили два поведения packaging.')
    h('Почему равенство здесь мало говорит о границах метода')
    p('Все шесть пар достигли потолка. У каждого пакета специально выбрано документированное изменение с компактным интерфейсом. Названия функций и возможные виды ответа известны модели. Полезность воспоминания на редких недокументированных изменениях или при дорогом поиске входа этими результатами не установлена.')
    source('История packaging 22.0','https://github.com/pypa/packaging/blob/22.0/CHANGELOG.rst');source('История PyJWT','https://pyjwt.readthedocs.io/en/2.0.1/changelog.html');source('История more-itertools','https://more-itertools.readthedocs.io/en/v8.14.0/versions.html')
def resources():
    page('Ресурсы и интерпретация','Что стоило выполнение и какую тему продолжать')
    allrows=[];tot=collections.Counter()
    for group,keys in [('Поиск, Sol',['search/runs']),('Поиск, Luna',['search_replication/runs']),('Искусственные API',['probe/runs1','probe/runs2']),('Релизы PyPI',['probe_real/runs1','probe_real/runs2'])]:
        att=[a for k in keys for f in (T/k).glob('*.json') for a in J(str(f.relative_to(T)))['attempts']]
        u=collections.Counter()
        for v in att:u.update(v['usage'])
        u['a']=len(att);u['ok']=sum(a['status']=='ok' for a in att);u['sec']=sum(a['elapsed_s'] for a in att);tot.update(u)
        allrows.append([group,u['a'],n(u['input_tokens']),n(u['cached_input_tokens']),n(u['output_tokens']),dec(u['sec'],1)])
    allrows.append(['Всего',tot['a'],n(tot['input_tokens']),n(tot['cached_input_tokens']),n(tot['output_tokens']),dec(tot['sec'],1)])
    tbl(['Стенд','Вызовов','Вход, всего','Кэшированный вход','Выход','Сумма, с'],allrows,[3.8,2.1,3.1,3.3,2.4,2.4],True)
    p('Вход и выход измерены в токенах. Кэшированный вход входит в общий вход. Показано время отдельных запросов в сумме. Некоторые запросы выполнялись параллельно. Рабочая температура и серверный seed не задавались. Фиксировались модельный псевдоним и низкая глубина рассуждения. Неизменность серверных весов в новых запусках не гарантирована. Две отдельные калибровки транспорта выполнены вне исследовательских выборок и сохранены в архиве.')
    h('Первый приоритет — проверить совместную стоимость на реальном инструменте')
    p('Зафиксировать на новом проекте обращения к сборке, отчёту тестов или API со многими полями. По начальной части истории выбрать восемь сохраняемых полей. На последующих задачах независимый исполнитель извлекает значения сам. Главные контроли — частотный и блочный кэши. Измерять полностью верный результат при лимите и полную стоимость с учётом построения памяти. Если экономия исчезает при учёте чтения текста и времени записи, практическая гипотеза не выдержала проверки.')
    h('Поиск — проверять передачу свидетельства и следующий ход')
    p('Вместо дополнительной JSON-формы полезнее проверить, сможет ли агент сам запросить манифест при неоднозначности, затем расширить поиск. Нужны настоящие issues, несколько допустимых действий и одинаковая общая цена. Наблюдаемая зависимость от модели делает репликацию на втором исполнителе обязательной для такого вывода.')
    h('Перенос пробы — искать условия, где свежая проверка дорога')
    p('На этих пакетах свежая проба достигла потолка. Следующий различающий тест потребует неизвестных реализаций с несколькими правдоподобными изменениями и сравнения с агентом, который сам конструирует проверку. Открытым остаётся вопрос, когда сохранённая проба сокращает число обращений при том же качестве.')
def sim_append():
    d=J('retention/results/summary.json')
    for k,lab in [('block','Чтение источника целиком'),('field','Поштучное чтение')]:
        page('Приложение   /   все условия симулятора',lab,'Каждая строка усредняет 128 запросов × 64 мира. Строки разных политик используют одни и те же задания. Полные журналы позволяют восстановить каждое вычисление.')
        rp=[]
        for rho in [0,50,100]:
            for policy,label in [('joint','Совместный'),('marginal','Частотный'),('whole_block','Блоки'),('recent','Недавние'),('validation_choice','По валидации')]:
                ds={v['metric']:v for v in d['estimates'] if (v['tool'],v['rho'],v['policy'])==(k,rho,policy)}
                rp.append([dec(rho/100,1),label,dec(ds['required_reads']['mean'],4),dec(ds['actual_reads']['mean'],4),dec(ds['returned_values']['mean'],4),perc(ds['correct']['mean'])])
        tbl(['ρ','Политика','Нужно чтений','Сделано чтений','Получено полей','Полный ответ'],rp,[1.2,3.65,3.0,3.15,3.15,2.95],True)
        h('Стоимость образования памяти')
        p('У всех политик одинаковый бюджет сохранённых значений — восемь. Для обучения совместного выбора нужны частоты подмножеств полей одного источника; при восьми источниках и четырёх полях возможны 120 непустых масок до учёта частот. Сравнение числа чтений условно на уже построенном кэше. В итоговую окупаемость реальной службы войдут работа компилятора, сбор прошлых запросов и переобучение при изменении источника.')
        if k=='field':
            doc.paragraphs[-1].text='При поштучном чтении выгода поля определяется частотой запроса этого поля. Совместная и частотная политики выбрали те же записи во всех 192 сочетаниях мира и режима. При построении каждого кэша делаются восемь записей (40 байт). За 128 тестовых запросов новых записей нет. Полное первичное чтение 32 полей требует 32 одиночных обращений либо восьми блочных. Эту стоимость важно учитывать при короткой серии задач.'
        if k=='block':
            p('Пример противоположных исходов в мире 916001 при ρ = 0. На шаге 36 совместный кэш сохранил поле 15 и прочитал 9 и 18 за два вызова. Частотному понадобилось три разных источника. На шаге 62 частотный кэш сохранил поле 31 и успел выполнить запрос, тогда как совместный его не сохранил.')
def records():
    page('Материалы и воспроизводимость','Как проверить результаты','Таблицы дают исходы экспериментов. Для точной проверки к документу приложены машинные записи каждого выполнения, исходные программы, распределение условий и ответы моделей.')
    h('Где лежат данные')
    p('Отдельный файл agent-memory-experiment-records.zip содержит ту же побайтовую копию, что и внутри DOCX. Если сохранился только Word-документ, откройте его копию любым ZIP-архиватором и извлеките word/embeddings/experiment-records.zip. Внутри находятся README_RU.md и контрольные суммы MANIFEST.sha256. Независимое воспроизведение исходов по сохранённым ответам не требует новых вызовов модели.')
    h('Какие действия записаны')
    p('Для модели сохранены точный видимый промпт, его хеш, JSON-события CLI, видимый ответ, отметки UTC и счётчики токенов. Для инструментов — параметры вызова, выход, проверенное эталонное значение и исход. Для симулятора — генератор, семена, наблюдения, выбор кэша, обращения за данными и вычисленный результат. Внутренние шаги рассуждения модели не наблюдались. Транспортные проверки вынесены отдельно.')
    h('Связь с предшествующими работами')
    source('Librarian — сохранение истории поиска по репозиторию',ar('2605.27787'))
    source('SWE-Explore — оценка локализации при ограниченном чтении',ar('2606.07297'))
    source('ToolAtlas — опыт взаимодействия с инструментом',ar('2607.11126'))
    source('Robust Function Calling — поведение при смене интерфейса',ar('2610.23342'))
    source('Learning What to Remember — стоимость повторного получения',ar('2606.10616'))
    source('VibeMemBench — опубликованные истории кодовых агентов',ar('2609.23570'))
    source('Kassis et al. — Scientific Agent Skills, методика планирования и анализа',ar('2609.00065'))
    h('Границы исследования')
    p('Это локально зафиксированные пилоты. Для долей успеха в искусственных задачах значим состав примеров. Формальные p и интервалы не описывают всю популяцию реальных репозиториев. Эксперимент со стоимостью показывает эффект внутри заданной модели данных. Полевые следы подтверждают наличие явления, а все причинные сравнения относятся только к исполненным вмешательствам.')
def main():
    front();study_design();search_pages();field_page();probe_pages();real_page();simulator();resources();appendix();sim_append();records()
    archive=OUT/'agent-memory-experiment-records.zip'
    part=Part(PackURI('/word/embeddings/experiment-records.zip'),'application/zip',archive.read_bytes(),doc.part.package)
    doc.part.relate_to(part,'http://schemas.openxmlformats.org/officeDocument/2006/relationships/package')
    doc.save(OUT/'agent-memory-experiment-results.docx')
if __name__=='__main__':main()

